const jsonHeaders={"content-type":"application/json; charset=utf-8","cache-control":"no-store"};
function corsHeaders(request){const origin=request.headers.get('origin');return {...jsonHeaders,"access-control-allow-origin":origin||"*","access-control-allow-headers":"content-type","access-control-allow-methods":"POST, OPTIONS","vary":"Origin"};}
function json(body,status,request){return new Response(JSON.stringify(body),{status,headers:corsHeaders(request)});}
function clean(value,max){return String(value??'').trim().slice(0,max);}
function validEmail(value){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)&&value.length<=160;}
export function validateSupportPayload(input){const payload={nome:clean(input?.nome,80),email:clean(input?.email,160).toLowerCase(),categoria:clean(input?.categoria,80),assunto:clean(input?.assunto,120),mensagem:clean(input?.mensagem,4000)};if(!payload.nome||!validEmail(payload.email)||!payload.assunto||!payload.mensagem)return {ok:false,error:'Preencha nome, e-mail, assunto e mensagem.'};return {ok:true,payload};}
async function sendSupportEmail(payload,env,fetchImpl=globalThis.fetch){const apiKey=String(env?.RESEND_API_KEY||'').trim();if(!apiKey)return {ok:false,status:503,code:'email_not_configured'};const to=String(env.SUPPORT_TO_EMAIL||'fixouestudos@gmail.com').trim();const from=String(env.SUPPORT_FROM_EMAIL||'FIXOU <onboarding@resend.dev>').trim();const response=await fetchImpl('https://api.resend.com/emails',{method:'POST',headers:{authorization:`Bearer ${apiKey}`,"content-type":"application/json"},body:JSON.stringify({from,to:[to],reply_to:payload.email,subject:`[FIXOU] ${payload.assunto}`,text:`Nome: ${payload.nome}\nE-mail: ${payload.email}\nCategoria: ${payload.categoria||'Outro'}\n\n${payload.mensagem}`})});let result={};try{result=await response.json();}catch{}if(!response.ok)return {ok:false,status:502,code:'email_provider_error',providerMessage:result?.message||'Falha no provedor de e-mail.'};return {ok:true,id:result?.id||null};}
export default {async fetch(request,env={}){const url=new URL(request.url);if(url.pathname==='/api/health'&&request.method==='GET')return json({ok:true,emailConfigured:!!String(env.RESEND_API_KEY||'').trim()},200,request);if(url.pathname!=='/api/support'){if(env.ASSETS?.fetch)return env.ASSETS.fetch(request);return new Response('FIXOU backend ativo.',{status:404});}if(request.method==='OPTIONS')return new Response(null,{status:204,headers:corsHeaders(request)});if(request.method!=='POST')return json({ok:false,error:'Método não permitido.'},405,request);const origin=request.headers.get('origin');if(origin){try{if(new URL(origin).host!==url.host)return json({ok:false,error:'Origem não permitida.'},403,request);}catch{return json({ok:false,error:'Origem inválida.'},403,request);}}let input;try{input=await request.json();}catch{return json({ok:false,error:'JSON inválido.'},400,request);}const parsed=validateSupportPayload(input);if(!parsed.ok)return json(parsed,400,request);try{const sent=await sendSupportEmail(parsed.payload,env);if(!sent.ok)return json({ok:false,code:sent.code,error:sent.providerMessage||'O e-mail ainda não está configurado no backend.'},sent.status,request);return json({ok:true,id:sent.id},200,request);}catch(error){return json({ok:false,code:'email_network_error',error:'Não foi possível conectar ao provedor de e-mail.'},502,request);}}};
